arguments.rscript:
# Load required packages
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(readr)

# Load files and check column names
wave4 <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t')
wave5 <- read_delim('data/input/wave_five_lsype_young_person_2020.tab', delim = '\t')
wave6 <- read_delim('data/input/wave_six_lsype_young_person_2020.tab', delim = '\t')
wave7 <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave8 <- read_delim('data/input/ns8_2015_derived.tab', delim = '\t')
wave9 <- read_delim('data/input/ns9_2022_derived_variables.tab', delim = '\t')

# Print column names for verification
cat("Wave 4 columns:", names(wave4), "\n")
cat("Wave 5 columns:", names(wave5), "\n")
cat("Wave 6 columns:", names(wave6), "\n")
cat("Wave 7 columns:", names(wave7), "\n")
cat("Wave 8 columns:", names(wave8), "\n")
cat("Wave 9 columns:", names(wave9), "\n")

# Load the full datasets for merging
wave1 <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t')

# Merge datasets
merged_data <- wave1
for (wave in list(wave4, wave5, wave6, wave7, wave8, wave9)) {
  merged_data <- full_join(merged_data, wave, by = 'NSID')
}

# Define correct variable names based on metadata
wave4_var <- grep('empsYP', names(wave4), value = TRUE)
wave5_var <- grep('mainactYP', names(wave5), value = TRUE)
wave6_var <- grep('TCurrentAct', names(wave6), value = TRUE)
wave7_var <- grep('TCurrentAct', names(wave7), value = TRUE)
wave8_var <- grep('DACTIVITYC', names(wave8), value = TRUE)
wave9_var <- grep('DACTIVITYC', names(wave9), value = TRUE)

# Print found variable names
cat("Found W4 variable:", wave4_var, "\n")
cat("Found W5 variable:", wave5_var, "\n")
cat("Found W6 variable:", wave6_var, "\n")
cat("Found W7 variable:", wave7_var, "\n")
cat("Found W8 variable:", wave8_var, "\n")
cat("Found W9 variable:", wave9_var, "\n")

# Use the correct variable names for processing
if (!is.null(wave4_var)) {
  merged_data$W4empsYP <- merged_data[[wave4_var]]
}
if (!is.null(wave5_var)) {
  merged_data$W5mainactYP <- merged_data[[wave5_var]]
}
if (!is.null(wave6_var)) {
  merged_data$W6TCurrentAct <- merged_data[[wave6_var]]
}
if (!is.null(wave7_var)) {
